Art Piece 2 Code
My second art piece uses generative packages in R. The functions defined below are part of the rayshader and ambient package. Descriptions for the following functions can be found in Danielle’s post.

library(rayshader)
library(ambient)


#Danielle's provided function
#produce coordinates to give to other functions
transform_to_curl_space &lt;- function(x, y, frequency = 1, octaves = 10) {
  curl_noise(
    generator = fracture,
    noise = gen_simplex,
    fractal = fbm,
    octaves = octaves,
    frequency = frequency,
    x = x,
    y = y
  )
}


#Danielle's provided function
#construct cells in the transformed space
define_worley_cells &lt;- function(x, y, frequency = 3, octaves = 6) {
  fracture(
    noise = gen_worley,
    fractal = billow,
    octaves = octaves,
    frequency = frequency,
    value = "cell",
    x = x,
    y = y
  ) |&gt;
    rank() |&gt; 
    normalise()
}


#Danielle's provided function
#adding offsets to coordinates
simplex_noise &lt;- function(x, y, frequency = .1, octaves = 10) {
  fracture(
    noise = gen_simplex,
    fractal = ridged,
    octaves = octaves,
    frequency = frequency,
    x = x,
    y = y
  ) |&gt;
    normalise()
}


#Danielle's provided function
#constructing floe using above functions
ice_floe &lt;- function(seed) {

  set.seed(seed)

  grid &lt;- long_grid(
    x = seq(0, 1, length.out = 2000),
    y = seq(0, 1, length.out = 2000)
  )

  coords &lt;- transform_to_curl_space(grid$x, grid$y)

  grid |&gt;
    mutate(
      cells = define_worley_cells(coords$x, coords$y),
      paint = simplex_noise(x + cells, y + cells),
      paint = normalise(paint)
    ) |&gt;
    as.array(value = paint)
}


#Danielle's provided function
#Adding shading to create a 3D effect
shaded_ice_floe &lt;- function(seed) {

  art &lt;- ice_floe(668)

  height_shade(
    heightmap = art,
    texture = sample_canva2(seed, n=10)
  ) |&gt;
    add_shadow(
      shadowmap = ray_shade(
        heightmap = art, 
        sunaltitude = 40, 
        sunangle = 195,
        multicore = TRUE, 
        zscale = .005
      ), 
      max_darken = .3
    ) |&gt;
    plot_map()
}

